// Same contract as gumroad_sales_to_csv.py: one clean row per sale_id, no dupes.
const FIELDS = ["sale_id","created_at_utc","product_name","product_id","price_cents","price_usd",
  "currency","buyer_email","buyer_name","country","refunded","license_key","utm_source","is_recurring"];
function transform(payload) {
  const rows = [], seen = new Set();
  for (const s of (payload.sales || [])) {
    if (!s.id || seen.has(s.id)) continue;
    seen.add(s.id);
    const price = Number(s.price || 0);
    const created = s.created_at ? new Date(s.created_at).toISOString().replace(/\.\d{3}Z$/, "Z") : "";
    rows.push({
      sale_id: s.id,
      created_at_utc: created,
      product_name: (s.product_name || "").trim(),
      product_id: s.product_id || "",
      price_cents: price,
      price_usd: price / 100,
      currency: s.currency || "usd",
      buyer_email: (s.email || "").trim().toLowerCase(),
      buyer_name: (s.full_name || s.name || "").trim(),
      country: (s.country || "").trim().toUpperCase(),
      refunded: !!s.refunded,
      license_key: s.license_key || "",
      utm_source: (s.utm_link && s.utm_link.utm_source) || s.referrer || "",
      is_recurring: !!s.subscription_id,
    });
  }
  rows.sort((a, b) => (a.created_at_utc < b.created_at_utc ? 1 : -1));
  return rows.map(r => ({ json: r }));
}
const all = [];
let page = $input.first().json;
for (let i = 0; i < 50; i++) {          // page through, 50 pages hard cap
  all.push(...transform(page));
  if (!page.next_page_key) break;
  page = await this.helpers.httpRequest({
    url: "https://api.gumroad.com/v2/sales",
    qs: { access_token: $env.GUMROAD_TOKEN, page_key: page.next_page_key },
    json: true,
  });
}
return all;
